class Lambda {
  constructor(handler, framework) {
    this.type = "Lambda";
    this.handler = handler;
    this.framework = framework;
  }
}
class NodejsLambda extends Lambda {
  constructor(handler, framework) {
    super(handler, framework);
    this.launcherType = "Nodejs";
    this.shouldAddHelpers = true;
  }
}
exports.Lambda = Lambda;
exports.NodejsLambda = NodejsLambda;
exports.makeLambda = (handler, slug) =>
  slug === undefined ? new Lambda(handler) : new NodejsLambda(handler, { slug, version: "1" });
